import assert from'node:assert/strict';import{readFileSync,mkdirSync,writeFileSync}from'node:fs';import{chromium,webkit}from'playwright';import{chapterCollections,chapterHash}from'../lib/practice-chapters.ts';
const base=process.env.KLINK_TEST_URL||'http://127.0.0.1:18996',out=process.env.KLINK_ENTER_OUTPUT||'outputs/enter-focus-20261101/local';mkdirSync(out,{recursive:true});const checks=[],errors=[];
for(const[engine,type]of Object.entries({chromium,webkit})){const b=await type.launch();try{for(const viewport of[{width:1280,height:800},{width:320,height:568}])for(const activity of['content-woordpakketten','text-question']){const p=await b.newPage({viewport,hasTouch:viewport.width===320});p.setDefaultTimeout(15000);p.on('pageerror',e=>errors.push(e.message));try{await p.addInitScript(()=>{localStorage.setItem('klink.enter.retention','kept');window.Audio=class extends EventTarget{play(){this.timer=setTimeout(()=>this.dispatchEvent(new Event('ended')),30);return Promise.resolve()}pause(){clearTimeout(this.timer)}}});const row=chapterCollections(activity).find(r=>activity==='text-question'?r.id==='klink-teksten-zelf-a1-r01-v1':r.id==='content:woordpakketten:word-self:b1:b1:choice'),es=row.contentUrl?JSON.parse(readFileSync('public'+row.contentUrl)).exercises:row.exercises,e=es[0];await p.goto(base+'/'+chapterHash({chapter:activity==='text-question'?'texts':'words',activity,collection:row.id,level:row.level,help:'practice'}));const root=p.locator('[data-exercise-id]');await root.waitFor();assert.equal(await root.getAttribute('data-exercise-id'),e.exerciseId);const info=p.getByRole('button',{name:'Over deze oefening',exact:true});await info.click();await p.getByRole('dialog').waitFor();await p.keyboard.press('Enter');await p.getByRole('dialog').waitFor({state:'hidden'});assert.equal(await root.getAttribute('data-exercise-id'),e.exerciseId);
const opts=p.locator('.cp-choice-grid > button, .cp-choice-grid > .cp-extended-option > button:first-child'),choices=e.contentTask?.options||e.options,correctIds=e.contentTask?.correctOptionIds||e.answer.correctOptionIds,correct=choices.findIndex(o=>correctIds.includes(o.id));let naturalFocusWasLost=false;if(activity==='content-woordpakketten'){const wrong=choices.findIndex(o=>!correctIds.includes(o.id));await opts.nth(wrong).click();await p.keyboard.press('Enter');assert.equal(await root.getAttribute('data-practice-ready'),'false');await p.keyboard.press('Enter');assert.equal(await root.getAttribute('data-exercise-id'),e.exerciseId);await opts.nth(correct).click();await p.keyboard.down('Enter');await p.keyboard.down('Enter');await p.keyboard.up('Enter');assert.equal(await root.getAttribute('data-practice-ready'),'true');assert.equal(await root.getAttribute('data-exercise-id'),e.exerciseId,'Held Enter must not skip the feedback');await p.screenshot({path:out+'/'+engine+'-'+viewport.width+'-selected-correct.png'});await p.keyboard.press('Enter');}else{await opts.nth(correct).click();assert.equal(await root.getAttribute('data-practice-ready'),'true');naturalFocusWasLost=await p.evaluate(()=>document.activeElement===document.body);await p.screenshot({path:out+'/'+engine+'-'+viewport.width+'-reading-correct.png'});await p.keyboard.down('Enter');await p.keyboard.down('Enter');await p.keyboard.up('Enter');}
await p.waitForTimeout(150);assert.equal(await p.locator('[data-exercise-id]').getAttribute('data-exercise-id'),es[1].exerciseId,'Exactly one next exercise without focusing Verder');if(activity==='text-question'){
 const second=es[1],correctSecond=second.options.findIndex(o=>second.answer.correctOptionIds.includes(o.id));
 await opts.nth(correctSecond).click();assert.equal(await root.getAttribute('data-practice-ready'),'true');
 await p.evaluate(()=>document.activeElement?.blur());assert(await p.evaluate(()=>document.activeElement===document.body));
 await p.keyboard.press('Enter');await p.waitForFunction(id=>document.querySelector('[data-exercise-id]')?.getAttribute('data-exercise-id')===id,es[2].exerciseId);
}
assert.equal(await p.evaluate(()=>localStorage.getItem('klink.enter.retention')),'kept');checks.push({engine,viewport,activity,enterFromActualFocus:true,naturalFocusWasLost,lostFocusFallbackTested:activity==='text-question',exactlyOneNext:true,heldEnterSafe:true,dialogNative:true,wrongCannotAdvance:activity==='content-woordpakketten',storagePreserved:true});}finally{await p.close();}}}finally{await b.close();writeFileSync(out+'/checks.json',JSON.stringify({base,checks,errors,physicalKeyboardTested:false},null,2)+'\n');}}
assert.equal(checks.length,8);assert.deepEqual(errors,[]);console.log('PASS 8 real mouse/Enter focus flows; wrong answer, held Enter, dialog and stored data preserved.');
